-- Disposable fixture security assertions. Never apply to hosted Supabase.
begin;
create schema worker_security_test;
create function worker_security_test.ok(value boolean,label text) returns void language plpgsql security invoker as $$begin if value is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function worker_security_test.denied(statement text,label text) returns void language plpgsql security invoker as $$begin begin execute statement;exception when insufficient_privilege then raise notice 'PASS %',label;return;end;raise exception 'FAIL % unexpectedly permitted',label;end$$;
grant usage on schema worker_security_test to castly_engagement_worker,castly_api;
grant execute on all functions in schema worker_security_test to castly_engagement_worker,castly_api;
select worker_security_test.ok((select not rolsuper and not rolbypassrls and not rolcreatedb and not rolcreaterole and not rolreplication and not rolinherit from pg_roles where rolname='castly_engagement_worker'),'worker role has no privileged attributes and is NOINHERIT');
select worker_security_test.ok(not exists(select 1 from pg_auth_members where member='castly_engagement_worker'::regrole),'worker has no role memberships');
select worker_security_test.ok(not exists(select 1 from pg_class where relowner='castly_engagement_worker'::regrole and relkind in('r','p')),'worker owns no application tables');
select worker_security_test.ok(not has_schema_privilege('castly_engagement_worker','public','CREATE') and not has_schema_privilege('castly_engagement_worker','engagement_private','CREATE'),'worker cannot create schema objects');
select worker_security_test.ok(not has_schema_privilege('castly_engagement_worker','auth','USAGE'),'worker has no auth schema usage');
select worker_security_test.ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private','trust_private','engagement_private') and p.prosecdef and has_function_privilege('castly_engagement_worker',p.oid,'EXECUTE')),'worker cannot execute application SECURITY DEFINER functions');
select worker_security_test.ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private','trust_private','engagement_private') and p.prosecdef and (p.proowner<>(select relowner from pg_class where oid='public.users'::regclass) or not coalesce(p.proconfig @> array['search_path=""'],false))),'existing definer functions have migration-owner ownership and pinned empty search_path');
select worker_security_test.ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='engagement_private' and p.prosecdef),'Phase6 queue helpers are all SECURITY INVOKER');
select worker_security_test.ok(not has_table_privilege('castly_engagement_worker','public.bookings','SELECT') and has_column_privilege('castly_engagement_worker','public.bookings','status','SELECT') and not has_column_privilege('castly_engagement_worker','public.bookings','requirements','SELECT'),'booking grants expose only required columns');
select worker_security_test.ok(not has_table_privilege('castly_engagement_worker','public.conversations','SELECT') and has_column_privilege('castly_engagement_worker','public.conversations','id','SELECT'),'conversation grants expose only required columns');
insert into auth.users(id) values('61000000-0000-0000-0000-000000000001'),('61000000-0000-0000-0000-000000000002'),('61000000-0000-0000-0000-000000000003'),('61000000-0000-0000-0000-000000000004');
update public.users set primary_role=case when id::text in('61000000-0000-0000-0000-000000000001','61000000-0000-0000-0000-000000000003') then 'client'::public.account_role else 'talent'::public.account_role end where id::text like '61000000-%';
insert into public.talent_profiles(id,display_name,category_id,city,day_rate,bio,skills,available,published) values('61000000-0000-0000-0000-000000000002','Worker fixture one','actors','Pune',1000,'Synthetic',array['acting'],true,true),('61000000-0000-0000-0000-000000000004','Worker fixture two','actors','Pune',1000,'Synthetic',array['acting'],true,true);
insert into public.bookings(id,client_id,talent_id,project_type,proposed_date,location,requirements,indicative_budget,status) values('62000000-0000-0000-0000-000000000001','61000000-0000-0000-0000-000000000001','61000000-0000-0000-0000-000000000002','Fixture',current_date+1,'Pune','Private requirements fixture',1000,'accepted'),('62000000-0000-0000-0000-000000000002','61000000-0000-0000-0000-000000000003','61000000-0000-0000-0000-000000000004','Fixture',current_date+1,'Pune','Unrelated private fixture',1000,'accepted');
insert into public.conversations(id,client_id,talent_id) values('63000000-0000-0000-0000-000000000001','61000000-0000-0000-0000-000000000001','61000000-0000-0000-0000-000000000002'),('63000000-0000-0000-0000-000000000002','61000000-0000-0000-0000-000000000003','61000000-0000-0000-0000-000000000004');
insert into public.engagement_preferences(user_id,push_bookings,email_transactional) values('61000000-0000-0000-0000-000000000001',true,true),('61000000-0000-0000-0000-000000000003',true,true);
insert into public.push_devices(id,user_id,device_key,token,platform) values('64000000-0000-0000-0000-000000000001','61000000-0000-0000-0000-000000000001',gen_random_uuid(),'ExpoPushToken[worker_security_one]','android'),('64000000-0000-0000-0000-000000000002','61000000-0000-0000-0000-000000000003',gen_random_uuid(),'ExpoPushToken[worker_security_two]','ios');
insert into engagement_private.contacts(user_id,email,verified_at) values('61000000-0000-0000-0000-000000000001','first@fixture.invalid',now()),('61000000-0000-0000-0000-000000000003','other@fixture.invalid',now());
insert into engagement_private.outbox(recipient_id,event_key,kind,channel,device_id,booking_id,conversation_id) values('61000000-0000-0000-0000-000000000001','worker-test:push','booking_accepted','push','64000000-0000-0000-0000-000000000001','62000000-0000-0000-0000-000000000001','63000000-0000-0000-0000-000000000001'),('61000000-0000-0000-0000-000000000001','worker-test:email','booking_accepted','email',null,'62000000-0000-0000-0000-000000000001','63000000-0000-0000-0000-000000000001');
set session authorization castly_engagement_worker;
select worker_security_test.ok(current_user='castly_engagement_worker' and session_user='castly_engagement_worker','SQL tests execute as the restricted worker');
select worker_security_test.ok(row_security_active('public.bookings'::regclass) and row_security_active('public.conversations'::regclass) and row_security_active('public.push_devices'::regclass),'worker actually remains subject to RLS');
select worker_security_test.ok((select count(*) from public.bookings where id='62000000-0000-0000-0000-000000000001')=1,'worker sees metadata for a valid delivery source');
select worker_security_test.ok((select count(*) from public.bookings where id='62000000-0000-0000-0000-000000000002')=0,'worker cannot enumerate unrelated bookings');
select worker_security_test.ok((select count(*) from public.conversations where id='63000000-0000-0000-0000-000000000001')=1,'worker sees queued conversation references');
select worker_security_test.ok((select count(*) from public.conversations where id='63000000-0000-0000-0000-000000000002')=0,'worker cannot enumerate unrelated conversations');
select worker_security_test.ok((select count(*) from public.push_devices where user_id='61000000-0000-0000-0000-000000000001')=1,'worker can resolve a queued device');
select worker_security_test.ok((select count(*) from public.push_devices where user_id='61000000-0000-0000-0000-000000000003')=0,'worker cannot enumerate unqueued tokens');
select worker_security_test.ok((select count(*) from engagement_private.contacts where user_id='61000000-0000-0000-0000-000000000001')=1,'worker can resolve a queued verified contact');
select worker_security_test.ok((select count(*) from engagement_private.contacts where user_id='61000000-0000-0000-0000-000000000003')=0,'worker cannot enumerate unqueued email contacts');
select worker_security_test.denied($q$select requirements from public.bookings$q$,'worker cannot read booking prose');
select worker_security_test.denied($q$select * from public.messages$q$,'worker cannot read message bodies');
select worker_security_test.denied($q$select * from public.users$q$,'worker cannot read private accounts');
select worker_security_test.denied($q$select * from public.subscription_orders$q$,'worker cannot read payment orders');
select worker_security_test.denied($q$select * from public.dispute_evidence$q$,'worker cannot read private evidence');
select worker_security_test.denied($q$update public.bookings set status='accepted'$q$,'worker cannot update booking transitions');
select worker_security_test.denied($q$update public.users set display_name='tampered'$q$,'worker cannot write private accounts');
select worker_security_test.denied($q$insert into engagement_private.outbox(recipient_id,event_key,kind,channel) values('61000000-0000-0000-0000-000000000003','forged','account_activity','email')$q$,'worker cannot manufacture notification sources');
select worker_security_test.denied($q$update engagement_private.outbox set recipient_id='61000000-0000-0000-0000-000000000003'$q$,'worker cannot retarget queue recipients');
select worker_security_test.denied($q$update engagement_private.outbox set booking_id='62000000-0000-0000-0000-000000000002'$q$,'worker cannot retarget queue business sources');
select worker_security_test.denied($q$select public.complete_onboarding('client','escalation')$q$,'worker cannot escalate through legacy definer RPC');
select worker_security_test.denied($q$set role castly_api$q$,'worker cannot switch to business API role');
select worker_security_test.denied($q$set role authenticated$q$,'worker cannot switch to authenticated role');
select worker_security_test.denied($q$grant castly_api to castly_engagement_worker$q$,'worker cannot grant itself role membership');
with job as(select id from engagement_private.outbox where state='queued' and event_key like 'worker-test:%' order by id for update skip locked limit 1),claimed as(update engagement_private.outbox o set state='sending',lease_until=now()+interval '1 minute' from job where o.id=job.id returning o.id)
select worker_security_test.ok((select count(*) from claimed)=1,'permitted queue claim succeeds under worker RLS');
select set_config('request.jwt.claim.sub','61000000-0000-0000-0000-000000000003',true);
select worker_security_test.ok((select count(*) from public.bookings where id='62000000-0000-0000-0000-000000000002')=0,'forged transaction claim cannot expand worker metadata scope');
reset session authorization;
select set_config('request.jwt.claim.sub','61000000-0000-0000-0000-000000000003',true);
set local role castly_api;
select worker_security_test.ok((select count(*) from engagement_private.outbox where recipient_id='61000000-0000-0000-0000-000000000001')=0,'ordinary actor cannot inspect another recipient outbox');
reset role;
rollback;
